insert into public.quiz_questions (quiz_id,position,type,prompt,explanation,media,options,answer_id,answer_ids,answer_bool,regions,board_art,accepted,placeholder,items,targets) values ('q-rec-deepest-places',1,'boolean','Aconcagua is the record of Highest peak in South America.','Aconcagua is South America''s highest peak.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',2,'boolean','Lake Baikal is the record of Deepest lake (commonly cited).','Baikal is the deepest freshwater lake by maximum depth.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',3,'boolean','Caspian Sea is the record of Largest inland water body.','The Caspian Sea is the largest inland water body.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',4,'boolean','Arctic Ocean is the record of Smallest named ocean.','The Arctic is the smallest of the five named oceans.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',5,'boolean','Kilimanjaro is the record of Highest peak in Africa.','Kilimanjaro is Africa''s highest peak.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',6,'boolean','Challenger Deep is the record of Deepest known ocean point.','Challenger Deep in the Mariana Trench is the deepest measured point.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',7,'boolean','China or Russia is the record of Country with the most neighbours (commonly cited).','China and Russia are typically listed with 14 land neighbours each, depending on recognition.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',8,'boolean','Atacama Desert is the place of Driest inhabited region often cited.','Parts of the Atacama receive virtually no rain for years.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',9,'boolean','Caspian Sea is the record of Largest lake overall by area if saline counts.','The Caspian is larger in area than any freshwater lake.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-deepest-places',10,'boolean','Ojos del Salado is the record of Highest volcano on Earth (commonly cited, Andes).','Ojos del Salado is often listed as the highest volcano.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',1,'boolean','Vinson Massif is the record of Highest peak in Antarctica.','Vinson is Antarctica''s highest peak.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',2,'boolean','La Paz (administrative) or Quito debate is the record of Highest capital city (commonly cited).','La Paz is often cited as the highest de facto administrative capital; Quito is among the highest official capitals.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',3,'boolean','United States and Canada is the record of Longest land border pair (commonly cited).','The US–Canada boundary is the world''s longest international land border.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',4,'boolean','Angel Falls is the record of Highest waterfall (commonly cited uninterrupted plunge).','Angel Falls in Venezuela is commonly cited as the world''s highest uninterrupted waterfall.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',5,'boolean','Elbrus or Mont Blanc depending on Caucasus inclusion is the record of Highest peak in Europe (often listed).','Elbrus is higher if the Caucasus counts as Europe; Mont Blanc is the Alpine high point.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',6,'boolean','Arabian Peninsula is the record of Largest peninsula (commonly cited).','The Arabian Peninsula is often listed as the world''s largest.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',7,'boolean','Antarctica is the record of Largest desert if Antarctica counts.','Antarctica is Earth''s largest desert by aridity and area.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',8,'boolean','Ganges–Brahmaputra–Meghna is the record of Largest delta (commonly cited).','The Bengal delta is among the world''s largest.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',9,'boolean','Nile or Amazon is the record of Longest river (often listed, definition-dependent).','Nile and Amazon compete depending on the source and measurement method.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-record-classroom',10,'boolean','Yellowstone is the place of Largest hot-spring or geyser basins famous site.','Yellowstone has the largest concentration of geysers.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',1,'boolean','Amazon is the record of River with the greatest discharge.','The Amazon has the largest discharge.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',2,'boolean','Lake Superior is the record of Largest freshwater lake by surface area.','Superior is the largest freshwater lake by area.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',3,'boolean','world''s largest metropolitan areas is the record of Largest city proper populations change often; a stable fact: Tokyo metro is among.','The Tokyo metropolitan area is consistently among the world''s largest.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',4,'boolean','Volga is the record of Longest river in Europe.','The Volga is the longest river in Europe.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',5,'boolean','Sicily is the record of Largest island in the Mediterranean.','Sicily is the Mediterranean''s largest island.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',6,'boolean','Nile is the record of Longest river in Africa (classic teaching).','The Nile is classically taught as Africa''s longest river.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',7,'boolean','Greenland is the record of Largest island.','Greenland is the world''s largest island (Australia is a continent).',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',8,'boolean','global mid-ocean ridge is the record of Mid-ocean ridge as longest mountain system.','The mid-ocean ridge system is Earth''s longest mountain chain if submarine ranges count.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',9,'boolean','Monaco or Vatican if included is the record of Smallest UN member by area (commonly cited).','Vatican City is the smallest state; among UN members, Monaco is among the smallest.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-biggest-basins',10,'boolean','Missouri–Mississippi is the record of Longest river in the United States (Missouri–Mississippi system).','The Missouri–Mississippi combination is the longest US river system.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',1,'boolean','Sahara is the record of Largest hot desert.','The Sahara is the largest hot desert.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',2,'boolean','Indonesia or Sweden/Finland depending on definition is the note of Largest archipelagic country by island count (commonly cited).','Indonesia is the largest archipelagic state by area and a leading island count; Nordic lake-island counts differ.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',3,'boolean','Mount Everest is the record of Highest mountain above sea level.','Everest is the highest peak above mean sea level.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',4,'boolean','Burj Khalifa is the record of Tallest building (as of the 2010s–2020s).','The Burj Khalifa in Dubai has been the tallest building since 2010.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',5,'boolean','Pantanal is the record of Largest tropical wetland (commonly cited).','The Pantanal is often cited as the world''s largest tropical wetland.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',6,'boolean','Puncak Jaya is the record of Highest peak in Oceania (Puncak Jaya).','Puncak Jaya on New Guinea is Oceania''s highest peak.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',7,'boolean','Andes is the record of Longest mountain range on land.','The Andes are the longest continental mountain range.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',8,'boolean','France (including overseas lands) is the record of Most time zones in one country (commonly cited).','France spans many time zones because of overseas territories.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',9,'boolean','Vostok, Antarctica is the place of Coldest air temperature recorded at a surface station (commonly cited).','Vostok Station recorded −89.2 °C in 1983.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-extreme-coasts',10,'boolean','Don Juan Pond or Dead Sea depending on measure is the note of Saltiest widely known water body.','The Dead Sea is among the saltiest large water bodies; some Antarctic ponds are saltier.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-super-size-set',1,'boolean','Dead Sea shore is the record of Lowest land elevation on Earth (commonly cited).','The Dead Sea shoreline is the lowest exposed land elevation.',NULL,NULL,NULL,NULL,true,NULL,NULL,NULL,NULL,NULL,NULL),('q-rec-super-size-set',2,'boolean','Great Barrier Reef is the record of Largest coral reef system.','The Great Barrier Reef is the world''s largest